import { dateRangeForPreset, formatDate, formatDateRange } from "../../date-utils.js";
import { aggregateStudents, calculateAverageDuration, calculateTotalDuration, filterVisits, groupVisitsByDate, groupVisitsByIntervention, groupVisitsByReason, groupVisitsByRoom, summarize, sortNewest } from "./pace-analytics.js";
import { dateRangeControl } from "../../components/date-range.js";
import { emptyState, esc, formatMinutes, metricCard, pill } from "../../components/html.js";
import { FOLLOW_UP_STATUS, FOLLOW_UP_STATUS_LABELS, followUpCounts, followUpEntries, followUpFor, followUpStatusLabel, matchesFollowUpStatus } from "./pace-follow-up.js";
import { ADMIN_MUTATION_ACTIONS, REVIEW_STATUS, REVIEW_STATUS_LABELS, activeVisits, adminHistoryFor, adminNotesFor, adminReviewFor, isVoided, reviewCounts, reviewStatusLabel, matchesReviewStatus } from "./pace-admin.js";

function header(title, subtitle, range, section = "Overview") {
  return `<div class="page-header"><div><div class="eyebrow">PACE / ${esc(section)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${dateRangeControl(range)}</div>`;
}

function barList(title, rows, empty = "No data in this range.") {
  const max = Math.max(...rows.map(row => row.count), 1);
  return `<section class="panel chart-panel"><div class="panel-heading"><div><h2>${esc(title)}</h2><p>Completed visits in the selected range</p></div></div>${rows.length ? `<div class="bar-list">${rows.slice(0, 7).map(row => `<div class="bar-row"><div class="bar-label" title="${esc(row.label)}">${esc(row.label)}</div><div class="bar-track"><span style="width:${Math.max(4, row.count / max * 100)}%"></span></div><div class="bar-count">${row.count}</div></div>`).join("")}</div>` : emptyState("No activity yet", empty)}</section>`;
}

function trendChart(rows) {
  if (!rows.length) return emptyState("No visits in this range", "Daily activity will appear here when PACE visits are available.");
  const max = Math.max(...rows.map(row => row.count), 1);
  const minWidth = Math.max(720, rows.length * 44);
  return `<div class="trend-chart-viewport" role="region" aria-label="Visits over time; horizontally scrollable" tabindex="0"><div class="trend-chart" role="img" aria-label="Visits by date" style="--trend-min-width:${minWidth}px">${rows.map(row => `<div class="trend-column"><div class="trend-count">${row.count}</div><div class="trend-bar" style="height:${Math.max(8, row.count / max * 110)}px"></div><div class="trend-label">${esc(formatDate(row.label, { month: "short", day: "numeric" }))}</div></div>`).join("")}</div></div>`;
}

function followUpBadge(followUp, showEmpty = false) {
  if (!followUp) return showEmpty ? `<span class="follow-up-none">No follow-up</span>` : `<span class="muted">—</span>`;
  const tone = followUp.status === FOLLOW_UP_STATUS.COMPLETE ? "complete" : followUp.status === FOLLOW_UP_STATUS.IN_REVIEW ? "review" : "needs";
  return `<span class="follow-up-badge follow-up-${tone}">${esc(followUpStatusLabel(followUp.status))}</span>`;
}

function followUpDate(value) { return formatDate(value, { month: "short", day: "numeric", year: "numeric" }); }

function followUpSection(visit, followUp, demo) {
  if (!demo) return `<section class="follow-up-section"><div class="follow-up-heading"><div><div class="eyebrow">Separate workflow</div><h3>Follow-Up</h3></div></div><p class="follow-up-copy">The follow-up workflow is available in the synthetic demo only. Historical PACE records remain read-only.</p></section>`;
  if (!followUp) return `<section class="follow-up-section"><div class="follow-up-heading"><div><div class="eyebrow">Separate workflow</div><h3>Follow-Up</h3></div>${followUpBadge(null, true)}</div><p class="follow-up-copy">No follow-up has been requested.</p><button class="button primary compact-button" data-follow-up-action="flag">Flag for Follow-Up</button></section>`;
  if (followUp.status === FOLLOW_UP_STATUS.NEEDS_REVIEW) return `<section class="follow-up-section"><div class="follow-up-heading"><div><div class="eyebrow">Separate workflow</div><h3>Follow-Up</h3></div>${followUpBadge(followUp)}</div><dl class="follow-up-meta"><div><dt>Flagged by</dt><dd>${esc(followUp.flaggedBy)}</dd></div><div><dt>Flagged</dt><dd>${esc(followUpDate(followUp.flaggedAt))}</dd></div></dl><button class="button primary compact-button" data-follow-up-action="start-review">Start Review</button></section>`;
  if (followUp.status === FOLLOW_UP_STATUS.IN_REVIEW) return `<section class="follow-up-section"><div class="follow-up-heading"><div><div class="eyebrow">Separate workflow</div><h3>Follow-Up</h3></div>${followUpBadge(followUp)}</div><dl class="follow-up-meta"><div><dt>Reviewed by</dt><dd>${esc(followUp.reviewedBy)}</dd></div><div><dt>Started</dt><dd>${esc(followUpDate(followUp.reviewedAt))}</dd></div></dl><label class="follow-up-note-field"><span>Follow-Up Note</span><textarea id="followUpNote" rows="3" placeholder="Add a short administrative follow-up note">${esc(followUp.followUpNote)}</textarea></label><button class="button primary compact-button" data-follow-up-action="complete">Complete Follow-Up</button></section>`;
  return `<section class="follow-up-section"><div class="follow-up-heading"><div><div class="eyebrow">Separate workflow</div><h3>Follow-Up</h3></div>${followUpBadge(followUp)}</div><dl class="follow-up-meta"><div><dt>Completed by</dt><dd>${esc(followUp.completedBy)}</dd></div><div><dt>Completed</dt><dd>${esc(followUpDate(followUp.completedAt))}</dd></div></dl><div class="follow-up-note"><span>Follow-Up Note</span><p>${esc(followUp.followUpNote || "No note recorded.")}</p></div></section>`;
}

function changedSinceReview(visit, review) {
  return review.status === REVIEW_STATUS.REVIEWED && review.sourceVersion !== null && review.sourceVersion !== undefined && String(visit.adminVersion ?? 1) !== String(review.sourceVersion);
}

function adminEditSection(visit, review, demo, mutationError = "", production = {}) {
  const changed = changedSinceReview(visit, review);
  const enabled = demo || (production.apiReady === true && production.writesEnabled === true);
  if (!enabled) return `<section class="admin-review-section"><div class="follow-up-heading"><div><div class="eyebrow">Administrative controls</div><h3>Review and editing</h3></div><span class="read-only-label">Production writes disabled</span></div><p class="follow-up-copy">Edit Submission is prepared for the protected production service, but production writes remain disabled until approved permissions, running-note storage and audit controls are verified.</p></section>`;
  const option = (value, label) => `<option value="${value}" ${review.status === value ? "selected" : ""}>${label}</option>`;
  const notes = adminNotesFor({ [visit.id]: review }, visit.id);
  const notesMarkup = notes.length ? notes.map(note => `<div class="admin-note-row"><strong>${esc(note.text)}</strong><span>${esc(note.actor)} · ${esc(note.createdAt)}</span></div>`).join("") : `<p class="muted">No administrative notes recorded.</p>`;
  const workflowLabel = demo ? "Synthetic workflow" : "Protected production workflow";
  return `<section class="admin-review-section"><div class="follow-up-heading"><div><div class="eyebrow">${workflowLabel}</div><h3>Administrative review</h3></div><span class="follow-up-badge follow-up-${review.isVoided ? "needs" : review.status === REVIEW_STATUS.REVIEWED ? "complete" : "review"}">${review.isVoided ? "Voided" : esc(reviewStatusLabel(review.status))}</span></div>${changed ? `<p class="admin-warning" role="status">This submission changed after it was reviewed. Review it again before relying on the previous status.</p>` : ""}${mutationError ? `<p class="admin-error" role="alert">${esc(mutationError)}</p>` : ""}<div class="admin-edit-grid"><label><span>Student</span><input id="adminStudent" value="${esc(visit.student)}"></label><label><span>Visit date</span><input id="adminDate" type="date" value="${esc(visit.date)}"></label><label><span>Teacher came from</span><input id="adminTeacher" value="${esc(visit.teacherCameFrom)}"></label><label><span>PACE room</span><input id="adminRoom" value="${esc(visit.room)}"></label><label><span>Behavior specialist</span><input id="adminSpecialists" value="${esc(visit.specialists.join(", "))}"></label><label><span>Time In</span><input id="adminTimeIn" value="${esc(visit.timeIn)}" placeholder="HH:MM"></label><label><span>Time Out</span><input id="adminTimeOut" value="${esc(visit.timeOut)}" placeholder="HH:MM"></label><label><span>Reason</span><input id="adminReasons" value="${esc(visit.reasons.join(", "))}"></label><label><span>Intervention / support</span><input id="adminInterventions" value="${esc(visit.interventions.join(", "))}"></label><label><span>SCM</span><select id="adminScm"><option value="" ${visit.scmUsed === null ? "selected" : ""}>Not recorded</option><option value="true" ${visit.scmUsed === true ? "selected" : ""}>Yes</option><option value="false" ${visit.scmUsed === false ? "selected" : ""}>No</option></select></label><label><span>Return status</span><input id="adminReturnStatus" value="${esc(visit.returnStatus)}"></label><label class="admin-edit-wide"><span>Original staff notes</span><textarea id="adminNotesSource" rows="3">${esc(visit.notes)}</textarea></label><label class="admin-edit-wide"><span>Correction reason (required to save changes)</span><input id="adminCorrectionReason" placeholder="Why is this correction needed?"></label></div><button class="button primary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.EDIT}">Edit Submission</button><div class="admin-review-fields"><label><span>Review status</span><select id="adminReviewStatus">${option(REVIEW_STATUS.UNREVIEWED, REVIEW_STATUS_LABELS[REVIEW_STATUS.UNREVIEWED])}${option(REVIEW_STATUS.REVIEWED, REVIEW_STATUS_LABELS[REVIEW_STATUS.REVIEWED])}${option(REVIEW_STATUS.NEEDS_FOLLOW_UP, REVIEW_STATUS_LABELS[REVIEW_STATUS.NEEDS_FOLLOW_UP])}</select></label><label><span>Follow-up status</span><select id="adminFollowUpStatus"><option value="open" ${review.followUpStatus === "open" ? "selected" : ""}>Open</option><option value="in-progress" ${review.followUpStatus === "in-progress" ? "selected" : ""}>In Progress</option><option value="resolved" ${review.followUpStatus === "resolved" ? "selected" : ""}>Resolved</option></select></label><label><span>Assigned to</span><input id="adminFollowUpAssignedTo" value="${esc(review.followUpAssignedTo)}"></label><label><span>Due date</span><input id="adminFollowUpDueDate" type="date" value="${esc(review.followUpDueDate)}"></label><label class="admin-edit-wide"><span>Add administrative note</span><textarea id="adminNoteText" rows="2" placeholder="Add a chronological note without changing the original submission"></textarea></label></div><div class="admin-notes-list"><h4>Administrative notes</h4>${notesMarkup}<button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.ADD_NOTE}">Add note</button></div><label class="admin-edit-wide admin-review-reason"><span>Review reason</span><input id="adminReviewReason" placeholder="Optional reason for saving review status"></label><div class="detail-actions"><button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.MARK_VIEWED}">Mark as viewed</button><button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.REVIEW}">Save review</button></div>${review.isVoided ? `<button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.RESTORE}">Restore submission</button>` : `<label class="admin-edit-wide admin-void-field"><span>Void reason (required)</span><textarea id="adminVoidReason" rows="2" placeholder="Why is this submission being voided?"></textarea></label><button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.VOID}">Void submission</button>`}<div class="admin-history"><h4>Administrative history</h4>${adminHistoryFor({ [visit.id]: review }, visit.id).length ? adminHistoryFor({ [visit.id]: review }, visit.id).slice().reverse().map(item => `<div class="admin-history-row"><strong>${esc(item.action)}</strong><span>${esc(item.actor)} · ${esc(item.at)}</span><small>${esc(item.reason || "")}</small></div>`).join("") : `<p class="muted">No administrative actions recorded.</p>`}</div></section>`;
}

function legacyDetailModal(visit, followUps, demo, adminReviews = {}, mutationError = "", production = {}) {
  if (!visit) return "";
  const followUp = followUpFor(followUps, visit.id);
  const review = adminReviewFor(adminReviews, visit.id);
  const field = (label, value) => `<div class="detail-field"><dt>${esc(label)}</dt><dd>${value ? esc(value) : "<span class=\"muted\">Not recorded</span>"}</dd></div>`;
  return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="visit-detail-title"><button class="modal-close" data-close-modal aria-label="Close">×</button><div class="eyebrow">PACE visit detail</div><h2 id="visit-detail-title">${esc(visit.student || "Unnamed student")}</h2><p class="modal-subtitle">${esc(formatDate(visit.date))} · ${esc(visit.timeIn || "Time not recorded")}${visit.timeOut ? `–${esc(visit.timeOut)}` : ""}${isVoided(visit, adminReviews) ? " · Voided" : ""}</p><div class="source-record-heading"><h3>PACE Visit</h3><span class="read-only-label">Original source record preserved</span></div><dl class="detail-grid">${field("Duration", formatMinutes(visit.durationMinutes))}${field("Room", visit.room)}${field("Reason", visit.reasons.join(", "))}${field("Intervention / support", visit.interventions.join(", "))}${field("Behavior specialist", visit.specialists.join(", "))}${field("Teacher came from", visit.teacherCameFrom)}${field("SCM", visit.scmUsed === null ? "Not recorded" : visit.scmUsed ? "Yes" : "No")}${field("Notes", visit.notes)}</dl><p class="read-only-note">Synthetic changes use the stable visit ID and remain in memory only. Production changes are fail-closed until approved storage, permissions and history controls are verified.</p>${adminEditSection(visit, review, demo, mutationError, production)}${followUpSection(visit, followUp, demo)}</section></div>`;
}

function adminTimestamp(value) {
  if (!value) return "Unknown time";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
}

function adminActionLabel(action) {
  return { edit: "Correction saved", review: "Review status saved", "mark-viewed": "Marked as viewed", "add-note": "Administrative note added", void: "Submission voided", restore: "Submission restored" }[action] ?? String(action || "Administrative action");
}

function historyMarkup(review) {
  const history = adminHistoryFor({ [review.visitId]: review }, review.visitId).slice().reverse();
  if (!history.length) return `<p class="muted">No administrative actions recorded.</p>`;
  return history.map(item => {
    const changed = item.fields?.length ? `<div class="history-fields"><strong>Changed fields:</strong> ${esc(item.fields.join(", "))}</div>` : "";
    const values = item.previous && item.updated && item.fields?.length ? item.fields.map(field => `<div class="history-value"><span>${esc(field)}</span><span>${esc(String(item.previous[field] ?? "Not recorded"))} → ${esc(String(item.updated[field] ?? "Not recorded"))}</span></div>`).join("") : "";
    return `<li class="admin-history-row"><strong>${esc(adminActionLabel(item.action))}</strong><span>${esc(item.actor || "Unknown actor")} · ${esc(adminTimestamp(item.at))}</span>${item.reason ? `<small>Reason: ${esc(item.reason)}</small>` : ""}${changed}${values ? `<div class="history-values">${values}</div>` : ""}</li>`;
  }).join("");
}

function primaryAttentionStatus(review, followUp) {
  if (review.isVoided) return { label: "Voided", tone: "voided" };
  if (followUp?.status === FOLLOW_UP_STATUS.NEEDS_REVIEW) return { label: "Needs Review", tone: "needs" };
  if (followUp?.status === FOLLOW_UP_STATUS.IN_REVIEW) return { label: "In Review", tone: "review" };
  if (followUp?.status === FOLLOW_UP_STATUS.COMPLETE) return { label: "Follow-Up Complete", tone: "complete" };
  if (review.status === REVIEW_STATUS.NEEDS_FOLLOW_UP) return { label: "Needs Follow-Up", tone: "needs" };
  if (review.status === REVIEW_STATUS.REVIEWED) return { label: "Reviewed", tone: "complete" };
  return { label: "Needs Review", tone: "needs" };
}

function statusSummary(review, followUp) {
  const primary = primaryAttentionStatus(review, followUp);
  const context = followUp && followUp.status !== FOLLOW_UP_STATUS.COMPLETE ? "Follow-up requested" : review.status === REVIEW_STATUS.NEEDS_FOLLOW_UP && !followUp ? "Review flag active" : "";
  return `<span class="status-badge status-${primary.tone}">${esc(primary.label)}</span><span class="status-meta">${review.status === REVIEW_STATUS.REVIEWED ? "Viewed" : "Not viewed"}</span>${context ? `<span class="status-context">${esc(context)}</span>` : ""}`;
}

function detailActions(visit, review, followUp) {
  const isFlagged = Boolean(followUp) || review.status === REVIEW_STATUS.NEEDS_FOLLOW_UP;
  const primary = isFlagged ? `<button class="button secondary compact-button" data-modal-action="review">Manage Review</button>` : `<button class="button primary compact-button" data-modal-action="review" data-follow-up-action="flag">Flag for Review</button>`;
  const viewed = review.status === REVIEW_STATUS.REVIEWED ? `<span class="action-status action-status-complete">Viewed</span>` : `<button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.MARK_VIEWED}">Mark as Viewed</button>`;
  return `<div class="visit-actions" aria-label="Administrative actions">${primary}${viewed}</div>`;
}

function flagPanel(review, followUp, demo) {
  if (!demo) return `<section class="flag-panel"><div class="section-heading"><div><div class="eyebrow">Review flag</div><h3>Flag management</h3></div><button class="text-button" data-modal-action="close-flag">Close</button></div><p class="follow-up-copy">Production review actions are available through the protected service when enabled.</p></section>`;
  return `<section class="flag-panel"><div class="section-heading"><div><div class="eyebrow">Review flag</div><h3>${followUp ? "Manage review flag" : "Flag this visit for review"}</h3></div><button class="text-button" data-modal-action="close-flag">Close</button></div><p class="follow-up-copy">This keeps the original PACE submission unchanged and creates review metadata for the administrative queue.</p><div class="flag-grid"><label><span>Review reason</span><input id="adminReviewReason" placeholder="Why does this visit need review?"></label><label><span>Assigned to <em>Optional</em></span><input id="adminFollowUpAssignedTo" value="${esc(review.followUpAssignedTo)}"></label><label><span>Due date <em>Optional</em></span><input id="adminFollowUpDueDate" type="date" value="${esc(review.followUpDueDate)}"></label><div class="flag-current"><span>Current follow-up status</span>${followUp ? followUpBadge(followUp) : `<span class="follow-up-none">No follow-up</span>`}</div></div><button class="button primary compact-button" data-admin-action="save-flag">Save Flag</button></section>`;
}

function notesMarkup(review, ui) {
  const notes = adminNotesFor({ [review.visitId]: review }, review.visitId);
  const list = notes.length ? `<ol class="admin-note-list">${notes.map(note => `<li class="admin-note-row"><strong>${esc(note.text)}</strong><span>${esc(note.actor || "Unknown author")} · ${esc(adminTimestamp(note.createdAt))}</span></li>`).join("")}</ol>` : `<p class="muted">No administrative notes recorded.</p>`;
  const add = ui.noteOpen ? `<div class="note-entry"><label><span>Add administrative note</span><textarea id="adminNoteText" rows="3" placeholder="Add a chronological note without changing the original submission"></textarea></label><div class="inline-actions"><button class="button primary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.ADD_NOTE}">Save Note</button><button class="button secondary compact-button" data-modal-action="close-note">Cancel</button></div></div>` : `<button class="button secondary compact-button" data-modal-action="add-note">Add Note</button>`;
  return `<section class="detail-section notes-section"><div class="section-heading"><div><div class="eyebrow">Administrative notes</div><h3>Running notes</h3></div></div>${list}${add}</section>`;
}

function moreActionsMarkup(visit, review, ui) {
  const control = review.isVoided ? `<button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.RESTORE}">Restore Submission</button>` : `<label class="admin-void-field"><span>Void reason (required)</span><textarea id="adminVoidReason" rows="2" placeholder="Why is this submission being voided?"></textarea></label><button class="button secondary compact-button danger-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.VOID}">Void Submission</button>`;
  return `<details class="secondary-actions" ${ui.moreOpen ? "open" : ""}><summary>More Administrative Actions</summary><div class="secondary-actions-body"><p>These actions preserve the original record and should be used only when necessary.</p>${control}</div></details>`;
}

function taskHeader(mode, title, description, icon, tone) {
  return `<div class="task-view-header task-view-${tone}"><div class="task-view-icon" aria-hidden="true">${icon}</div><div><div class="eyebrow">PACE / ${esc(mode)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p></div><button class="back-link task-back" data-modal-action="detail">← Back to Visit</button></div>`;
}

function reviewView(review, followUp, demo) {
  const attention = primaryAttentionStatus(review, followUp);
  const followUpDetails = followUp ? `<div class="review-status-card"><strong>${esc(followUpStatusLabel(followUp.status))}</strong><span>${followUp.status === FOLLOW_UP_STATUS.NEEDS_REVIEW ? "Waiting for an administrator to begin review." : followUp.status === FOLLOW_UP_STATUS.IN_REVIEW ? "Review is currently in progress." : "Follow-up has been completed."}</span></div>` : `<div class="review-status-card"><strong>No review flag</strong><span>Flag this visit when someone needs to look at it more closely.</span></div>`;
  const workflowAction = followUp?.status === FOLLOW_UP_STATUS.NEEDS_REVIEW ? `<button class="button primary compact-button" data-follow-up-action="start-review">Start Review</button>` : followUp?.status === FOLLOW_UP_STATUS.IN_REVIEW ? `<label class="follow-up-note-field"><span>Follow-Up Note</span><textarea id="followUpNote" rows="3" placeholder="Add a short follow-up note">${esc(followUp.followUpNote)}</textarea></label><button class="button primary compact-button" data-follow-up-action="complete">Complete Follow-Up</button>` : "";
  if (!demo) return `${taskHeader("REVIEW & FOLLOW-UP", "Review and follow-up", "See why this visit needs attention and record the next step.", "!", "review")}<div class="task-view-body"><div class="review-status-card"><strong>${esc(attention.label)}</strong><span>Production review actions are available through the protected service when enabled.</span></div></div>`;
  return `${taskHeader("REVIEW & FOLLOW-UP", followUp ? "Manage review and follow-up" : "Flag this visit for review", followUp ? "Keep the original submission unchanged while recording attention and next steps." : "Flagging creates review metadata without changing the original submission.", "!", "review")}<div class="task-view-body"><div class="review-status-grid">${followUpDetails}<div class="review-status-card"><strong>${review.status === REVIEW_STATUS.REVIEWED ? "Viewed" : "Not viewed"}</strong><span>${review.status === REVIEW_STATUS.REVIEWED ? "An administrator has opened and reviewed this visit." : "Mark as viewed when you have finished checking the submission."}</span></div></div><div class="flag-grid"><label><span>Review reason</span><input id="adminReviewReason" placeholder="Why does this visit need review?"></label><label><span>Assigned to <em>Optional</em></span><input id="adminFollowUpAssignedTo" value="${esc(review.followUpAssignedTo)}"></label><label><span>Due date <em>Optional</em></span><input id="adminFollowUpDueDate" type="date" value="${esc(review.followUpDueDate)}"></label></div><div class="inline-actions"><button class="button primary compact-button" data-admin-action="save-flag">Save Review Flag</button>${workflowAction}</div></div>`;
}

function notesList(review) {
  const notes = adminNotesFor({ [review.visitId]: review }, review.visitId);
  if (!notes.length) return `<p class="muted">No administrative notes have been added.</p>`;
  return `<ol class="admin-note-list">${notes.map(note => `<li class="admin-note-row"><strong>${esc(note.text)}</strong><span>${esc(note.actor || "Unknown author")} · ${esc(adminTimestamp(note.createdAt))}</span></li>`).join("")}</ol>`;
}

function notesView(review, demo) {
  const notes = adminNotesFor({ [review.visitId]: review }, review.visitId);
  if (!demo) return `${taskHeader("ADMINISTRATIVE NOTES", "Administrative notes", "Running notes are separate from the original staff submission.", "✎", "notes")}<div class="task-view-body"><p class="read-only-note">Administrative notes are available through the protected service when enabled.</p></div>`;
  return `${taskHeader("ADMINISTRATIVE NOTES", "Running administrative notes", "Add context for administrators without changing the original submission.", "✎", "notes")}<div class="task-view-body"><div class="task-count">${notes.length} note${notes.length === 1 ? "" : "s"}</div>${notesList(review)}<div class="note-entry"><label><span>Add administrative note</span><textarea id="adminNoteText" rows="4" placeholder="Write a short note for the administrative record"></textarea></label><div class="inline-actions"><button class="button primary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.ADD_NOTE}">Save Note</button><button class="button secondary compact-button" data-modal-action="detail">Cancel</button></div></div></div>`;
}

function historyView(review) {
  const history = adminHistoryFor({ [review.visitId]: review }, review.visitId);
  return `${taskHeader("RECORD HISTORY", "Administrative history", "See what changed, when it changed and why. The original submission remains preserved.", "▤", "history")}<div class="task-view-body"><div class="task-count">${history.length} recorded action${history.length === 1 ? "" : "s"}</div><ol class="admin-history-list">${historyMarkup(review)}</ol></div>`;
}

function moreView(review) {
  const control = review.isVoided ? `<div class="secondary-action-card"><strong>Restore this submission</strong><span>Restoring removes the void status. The original record and void history remain preserved.</span><button class="button secondary compact-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.RESTORE}">Restore Submission</button></div>` : `<div class="secondary-action-card secondary-action-danger"><strong>Void this submission</strong><span>Use only when the record should no longer appear in active PACE work. The original record remains preserved.</span><label class="admin-void-field"><span>Reason required</span><textarea id="adminVoidReason" rows="3" placeholder="Why should this submission be voided?"></textarea></label><button class="button secondary compact-button danger-button" data-admin-action="${ADMIN_MUTATION_ACTIONS.VOID}">Void Submission</button></div>`;
  return `${taskHeader("MORE ACTIONS", "More administrative actions", "These less common actions preserve the original record and history.", "!", "void")}<div class="task-view-body">${control}</div>`;
}

function editView(visit, review, demo, production = {}, mutationError = "", mutationNotice = "") {
  const enabled = demo || (production.apiReady === true && production.writesEnabled === true);
  if (!enabled) return `<div class="modal-panel-state"><p class="read-only-label">Production writes disabled</p><p>Editing is prepared for the protected production service but remains disabled until approved infrastructure is enabled.</p><button class="button secondary compact-button" data-modal-action="detail">Back to Visit Detail</button></div>`;
  return `${taskHeader("EDIT SUBMISSION", "Correct historical submission", "Update the effective visit details and explain the correction. The original submission remains preserved.", "✎", "correction")}${mutationNotice ? `<p class="admin-success" role="status">${esc(mutationNotice)}</p>` : ""}${mutationError ? `<p class="admin-error" role="alert">${esc(mutationError)}</p>` : ""}<div class="admin-edit-grid"><label><span>Student</span><input id="adminStudent" value="${esc(visit.student)}"></label><label><span>Visit date</span><input id="adminDate" type="date" value="${esc(visit.date)}"></label><label><span>Teacher came from</span><input id="adminTeacher" value="${esc(visit.teacherCameFrom)}"></label><label><span>PACE room</span><input id="adminRoom" value="${esc(visit.room)}"></label><label><span>Behavior specialist</span><input id="adminSpecialists" value="${esc(visit.specialists.join(", "))}"></label><label><span>Time In</span><input id="adminTimeIn" value="${esc(visit.timeIn)}" placeholder="HH:MM"></label><label><span>Time Out</span><input id="adminTimeOut" value="${esc(visit.timeOut)}" placeholder="HH:MM"></label><label><span>Reason</span><input id="adminReasons" value="${esc(visit.reasons.join(", "))}"></label><label><span>Intervention / support</span><input id="adminInterventions" value="${esc(visit.interventions.join(", "))}"></label><label><span>SCM</span><select id="adminScm"><option value="" ${visit.scmUsed === null ? "selected" : ""}>Not recorded</option><option value="true" ${visit.scmUsed === true ? "selected" : ""}>Yes</option><option value="false" ${visit.scmUsed === false ? "selected" : ""}>No</option></select></label><label><span>Return status</span><input id="adminReturnStatus" value="${esc(visit.returnStatus)}"></label><label class="admin-edit-wide"><span>Original staff notes</span><textarea id="adminNotesSource" rows="3">${esc(visit.notes)}</textarea></label><label class="admin-edit-wide"><span>Correction reason (required)</span><input id="adminCorrectionReason" placeholder="Why is this correction needed?"></label></div><div class="inline-actions edit-actions"><button class="button primary" data-admin-action="${ADMIN_MUTATION_ACTIONS.EDIT}">Save Correction</button><button class="button secondary" data-modal-action="detail">Cancel</button></div>`;
}

function legacyDetailView(visit, followUps, demo, adminReviews, mutationError, mutationNotice, production, ui) {
  const followUp = followUpFor(followUps, visit.id);
  const review = adminReviewFor(adminReviews, visit.id);
  const edited = (visit.adminVersion ?? 1) > 1 || adminHistoryFor({ [visit.id]: review }, visit.id).some(item => item.action === ADMIN_MUTATION_ACTIONS.EDIT);
  const changed = changedSinceReview(visit, review);
  const field = (label, value) => `<div class="detail-field"><dt>${esc(label)}</dt><dd>${value ? esc(value) : "<span class=\"muted\">Not recorded</span>"}</dd></div>`;
  return `<div class="visit-detail-view">${mutationNotice ? `<p class="admin-success" role="status">${esc(mutationNotice)}</p>` : ""}${mutationError ? `<p class="admin-error" role="alert">${esc(mutationError)}</p>` : ""}${changed ? `<p class="admin-warning" role="status">This submission changed after it was reviewed. Review it again before relying on the previous status.</p>` : ""}<div class="source-record-heading"><div><div class="eyebrow">Effective submission</div><h3>PACE Visit</h3></div>${edited ? `<span class="edited-indicator">Edited</span>` : `<span class="read-only-label">Original source record</span>`}</div><dl class="detail-grid">${field("Visit date", formatDate(visit.date))}${field("Time", `${visit.timeIn || "Not recorded"}${visit.timeOut ? `–${visit.timeOut}` : ""}`)}${field("Duration", formatMinutes(visit.durationMinutes))}${field("Student", visit.student)}${field("Room", visit.room)}${field("Reason", visit.reasons.join(", "))}${field("Intervention / support", visit.interventions.join(", "))}${field("Behavior specialist", visit.specialists.join(", "))}${field("Teacher came from", visit.teacherCameFrom)}${field("SCM", visit.scmUsed === null ? "Not recorded" : visit.scmUsed ? "Yes" : "No")}${field("Original staff notes", visit.notes)}${field("Return status", visit.returnStatus)}</dl><p class="read-only-note">Synthetic changes use the stable visit ID and remain in memory only. Production changes are fail-closed until approved storage, permissions and history controls are verified.</p>${detailActions(visit, review, followUp, demo, ui)}<button class="button secondary edit-entry-button" data-modal-action="edit">Need to Edit Submission?</button>${notesMarkup(review, ui)}<details class="history-disclosure" ${ui.historyOpen ? "open" : ""}><summary>Administrative History</summary><div class="history-disclosure-body"><p class="muted">Original submission values remain preserved. Corrections below describe administrative changes only.</p><ol class="admin-history-list">${historyMarkup(review)}</ol></div></details>${followUp ? `<section class="detail-section follow-up-summary"><div class="section-heading"><div><div class="eyebrow">Follow-up workflow</div><h3>Review flag</h3></div>${followUpBadge(followUp)}</div><dl class="follow-up-meta"><div><dt>Status</dt><dd>${esc(followUpStatusLabel(followUp.status))}</dd></div><div><dt>Flagged by</dt><dd>${esc(followUp.flaggedBy)}</dd></div></dl>${followUp.status === FOLLOW_UP_STATUS.NEEDS_REVIEW ? `<button class="button secondary compact-button" data-follow-up-action="start-review">Start Review</button>` : followUp.status === FOLLOW_UP_STATUS.IN_REVIEW ? `<label class="follow-up-note-field"><span>Follow-Up Note</span><textarea id="followUpNote" rows="3" placeholder="Add a short administrative follow-up note">${esc(followUp.followUpNote)}</textarea></label><button class="button primary compact-button" data-follow-up-action="complete">Complete Follow-Up</button>` : `<p class="follow-up-copy">Completed by ${esc(followUp.completedBy || "Administrator")} on ${esc(followUpDate(followUp.completedAt))}.</p>`}</section>` : ""}${moreActionsMarkup(visit, review, ui)}</div>`;
}

function detailView(visit, followUps, demo, adminReviews, mutationError, mutationNotice, production, ui) {
  const followUp = followUpFor(followUps, visit.id);
  const review = adminReviewFor(adminReviews, visit.id);
  const edited = (visit.adminVersion ?? 1) > 1 || adminHistoryFor({ [visit.id]: review }, visit.id).some(item => item.action === ADMIN_MUTATION_ACTIONS.EDIT);
  const changed = changedSinceReview(visit, review);
  const notesCount = adminNotesFor({ [visit.id]: review }, visit.id).length;
  const historyCount = adminHistoryFor({ [visit.id]: review }, visit.id).length;
  const flagged = Boolean(followUp) || review.status === REVIEW_STATUS.NEEDS_FOLLOW_UP;
  const field = (label, value) => `<div class="detail-field"><dt>${esc(label)}</dt><dd>${value ? esc(value) : "<span class=\"muted\">Not recorded</span>"}</dd></div>`;
  const reviewDetails = flagged ? `<section class="detail-section review-section"><div class="section-heading"><div><div class="eyebrow">Needs attention</div><h3>Review and follow-up</h3></div><span class="status-badge status-needs">${followUp ? esc(followUpStatusLabel(followUp.status)) : "Needs Follow-Up"}</span></div><p class="section-copy">${followUp?.status === FOLLOW_UP_STATUS.COMPLETE ? "Follow-up is complete. The original submission is unchanged." : "This visit has been flagged for additional attention."}</p><dl class="review-meta">${review.followUpAssignedTo ? `<div><dt>Assigned to</dt><dd>${esc(review.followUpAssignedTo)}</dd></div>` : ""}${review.followUpDueDate ? `<div><dt>Due date</dt><dd>${esc(formatDate(review.followUpDueDate))}</dd></div>` : ""}</dl><button class="button secondary compact-button" data-modal-action="review">Open Review & Follow-Up</button></section>` : "";
  return `<div class="visit-detail-view">${mutationNotice ? `<p class="admin-success" role="status">${esc(mutationNotice)}</p>` : ""}${mutationError ? `<p class="admin-error" role="alert">${esc(mutationError)}</p>` : ""}${changed ? `<p class="admin-warning" role="status">This submission changed after it was reviewed. Review it again before relying on the previous status.</p>` : ""}${detailActions(visit, review, followUp)}<section class="detail-section visit-summary-section"><div class="section-heading"><div><div class="eyebrow">Visit summary</div><h3>What happened</h3></div>${edited ? `<span class="edited-indicator">Edited</span>` : `<span class="read-only-label">Original preserved</span>`}</div><dl class="detail-grid">${field("Visit date", formatDate(visit.date))}${field("Time", `${visit.timeIn || "Not recorded"}${visit.timeOut ? `–${visit.timeOut}` : ""}`)}${field("Duration", formatMinutes(visit.durationMinutes))}${field("Student", visit.student)}${field("Room", visit.room)}${field("Reason", visit.reasons.join(", "))}${field("Intervention / support", visit.interventions.join(", "))}${field("Behavior specialist", visit.specialists.join(", "))}${field("Teacher came from", visit.teacherCameFrom)}${field("SCM", visit.scmUsed === null ? "Not recorded" : visit.scmUsed ? "Yes" : "No")}${field("Original staff notes", visit.notes)}${field("Return status", visit.returnStatus)}</dl><p class="read-only-note">Original submission preserved. Changes are recorded in the visit history.${demo ? " Demo changes are saved in this browser." : ""}</p></section>${reviewDetails}<div class="detail-entry-grid"><button class="detail-entry detail-entry-correction" data-modal-action="edit"><span class="detail-entry-icon" aria-hidden="true">✎</span><span><strong>Need to Edit Submission?</strong><small>Correct historical details with a reason.</small></span><span aria-hidden="true">→</span></button><button class="detail-entry detail-entry-notes" data-modal-action="notes"><span class="detail-entry-icon" aria-hidden="true">✎</span><span><strong>Administrative Notes <em>${notesCount}</em></strong><small>Add context without changing the original notes.</small></span><span aria-hidden="true">→</span></button><button class="detail-entry detail-entry-history" data-modal-action="history"><span class="detail-entry-icon" aria-hidden="true">▤</span><span><strong>Record History <em>${historyCount}</em></strong><small>See actions, reasons and preserved values.</small></span><span aria-hidden="true">→</span></button><button class="detail-entry detail-entry-more" data-modal-action="more"><span class="detail-entry-icon" aria-hidden="true">!</span><span><strong>More Actions</strong><small>Void or restore a submission when necessary.</small></span><span aria-hidden="true">→</span></button></div></div>`;
}

function detailModal(visit, followUps, demo, adminReviews = {}, mutationError = "", production = {}, ui = {}) {
  if (!visit) return "";
  const mode = ui.modalMode ?? "detail";
  const review = adminReviewFor(adminReviews, visit.id); const followUp = followUpFor(followUps, visit.id);
  const view = mode === "review" ? reviewView(review, followUp, demo) : mode === "edit" ? editView(visit, review, demo, production, mutationError, ui.mutationNotice) : mode === "notes" ? notesView(review, demo) : mode === "history" ? historyView(review) : mode === "more" ? moreView(review) : detailView(visit, followUps, demo, adminReviews, mutationError, ui.mutationNotice, production, ui);
  return `<div class="modal-backdrop" data-close-modal><section class="modal modal-visit" role="dialog" aria-modal="true" aria-labelledby="visit-detail-title"><header class="modal-header"><div class="modal-heading"><div class="eyebrow">PACE VISIT DETAIL</div><h2 id="visit-detail-title">${esc(visit.student || "Unnamed student")}</h2><p>${esc(formatDate(visit.date))} · ${esc(visit.timeIn || "Time not recorded")}${visit.timeOut ? `–${visit.timeOut}` : ""}</p><div class="modal-statuses">${statusSummary(review, followUp)}</div></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-scroll-region">${view}</div></section></div>`;
}

function followUpQueueEntry(entry) {
  const { visit, followUp } = entry;
  return `<button class="follow-up-queue-item" data-visit="${esc(visit.id)}"><span class="queue-main"><strong>${esc(visit.student || "Unnamed student")}</strong><span>${esc(formatDate(visit.date))} · ${esc(visit.timeIn || "Time not recorded")} · ${esc(visit.room || "Room not recorded")}</span><span>${esc(visit.reasons.join(", ") || "Reason not recorded")} · ${esc(visit.specialists.join(", ") || "Specialist not recorded")}</span></span>${followUpBadge(followUp)}</button>`;
}

function followUpQueueGroup(title, entries, emptyText) {
  return `<div class="follow-up-queue-group"><div class="queue-group-heading"><h3>${esc(title)}</h3><span>${entries.length}</span></div>${entries.length ? entries.slice(0, 4).map(followUpQueueEntry).join("") : `<p class="queue-empty">${esc(emptyText)}</p>`}</div>`;
}

function renderFollowUpQueue(visits, followUps, demo) {
  if (!demo) return "";
  const entries = followUpEntries(visits, followUps);
  const needs = entries.filter(entry => entry.followUp.status === FOLLOW_UP_STATUS.NEEDS_REVIEW).sort((a, b) => `${b.visit.date}|${b.visit.timeIn}`.localeCompare(`${a.visit.date}|${a.visit.timeIn}`));
  const reviewing = entries.filter(entry => entry.followUp.status === FOLLOW_UP_STATUS.IN_REVIEW).sort((a, b) => `${b.visit.date}|${b.visit.timeIn}`.localeCompare(`${a.visit.date}|${a.visit.timeIn}`));
  const complete = entries.filter(entry => entry.followUp.status === FOLLOW_UP_STATUS.COMPLETE).sort((a, b) => `${b.followUp.completedAt}`.localeCompare(`${a.followUp.completedAt}`));
  return `<section class="panel follow-up-queue"><div class="panel-heading"><div><div class="eyebrow">Separate workflow</div><h2>Follow-Up</h2><p>Small queue for visits that someone has chosen to review. Most visits have no follow-up.</p></div><span class="panel-meta">${entries.length} seeded examples</span></div><div class="follow-up-queue-grid">${followUpQueueGroup("Needs Review", needs, "Nothing waiting for attention.")}${followUpQueueGroup("In Review", reviewing, "No active reviews.")}${followUpQueueGroup("Recently Completed", complete, "No completed follow-ups yet.")}</div></section>`;
}

function renderReviewQueue(visits, reviews, demo) {
  if (!demo) return "";
  const counts = reviewCounts(visits, reviews);
  const item = (label, value, filter, tone = "") => `<button class="review-queue-item ${tone}" data-review-queue-filter="${filter}"><span>${esc(label)}</span><strong>${value}</strong></button>`;
  return `<section class="panel review-queue"><div class="panel-heading"><div><div class="eyebrow">Synthetic workflow</div><h2>Review Queue</h2><p>Administrative review metadata is simulated in this demo session.</p></div><span class="panel-meta">No production writes</span></div><div class="review-queue-grid">${item("Awaiting Review", counts.unreviewed, REVIEW_STATUS.UNREVIEWED)}${item("Reviewed", counts.reviewed, REVIEW_STATUS.REVIEWED, "complete")}${item("Needs Follow-Up", counts.needsFollowUp, REVIEW_STATUS.NEEDS_FOLLOW_UP, "needs")}${item("Voided Records", counts.voided, "voided", "voided")}</div></section>`;
}

export function renderHome(visits = [], range = dateRangeForPreset("30"), followUps = {}, activeVisit = null, demo = true, options = {}, adminReviews = {}, mutationError = "", production = {}, ui = {}) {
  return renderOverview(visits, range, followUps, activeVisit, demo, { home: true, title: "Admin Dashboard", subtitle: "PACE Operations & Insights", section: "Home" }, adminReviews, mutationError, production, ui);
}

export function renderOverview(visits, range, followUps, activeVisit, demo = true, options = {}, adminReviews = {}, mutationError = "", production = {}, ui = {}) {
  const visible = activeVisits(visits, adminReviews); const summary = summarize(visible, range); const completed = summary.records.filter(row => row.isCompleted);
  const trend = groupVisitsByDate(completed).sort((a, b) => a.label.localeCompare(b.label));
  const followUpRows = filterVisits(visible, range);
  const counts = followUpCounts(followUpRows, followUps);
  const title = options.title ?? "PACE Overview";
  const subtitle = options.subtitle ?? "A clear view of visits, supports and activity patterns.";
  const section = options.section ?? "Overview";
  const baseMetrics = `${metricCard("PACE visits", summary.visits, formatDateRange(range))}${metricCard("Unique students seen", summary.uniqueStudents, "Students with a completed visit")}${metricCard("Average visit duration", formatMinutes(summary.averageDuration), "Completed visits with duration")}${metricCard("SCM events", summary.scmEvents === null ? "—" : summary.scmEvents, summary.scmEvents === null ? "Not recorded in this range" : "SCM marked Yes")}`;
  const operationalMetrics = options.home ? "" : `${metricCard("Needs Review", counts.needsReview, "Waiting for administrative attention")}${metricCard("In Review", counts.inReview, "Follow-up currently underway")}${range.preset === "today" ? metricCard("Currently in PACE", summary.currentlyInPace, "Open visits dated today") : ""}`;
  return `${header(title, subtitle, range, section)}<div class="kpi-grid">${baseMetrics}${operationalMetrics}</div>${renderReviewQueue(filterVisits(visits, range), adminReviews, demo)}${renderFollowUpQueue(followUpRows, followUps, demo)}<div class="overview-grid"><section class="panel trend-panel"><div class="panel-heading"><div><h2>Visits over time</h2><p>How much PACE activity occurred on each day?</p></div><span class="panel-meta">${summary.visits} completed</span></div>${trendChart(trend)}</section>${barList("Reasons for visits", groupVisitsByReason(completed))}${barList("Interventions / supports", groupVisitsByIntervention(completed))}${barList("Visits by room", groupVisitsByRoom(completed))}</div>${activeVisit ? detailModal(activeVisit, followUps, demo, adminReviews, mutationError, production, ui) : ""}`;
}

export function renderStudents(visits, range, state, activeVisit) {
  const rows = aggregateStudents(filterVisits(activeVisits(visits, state.adminReviews), range)).filter(row => row.student.toLowerCase().includes((state.studentsSearch ?? "").toLowerCase())).sort((a, b) => { const field = state.studentsSort ?? "visits"; return typeof a[field] === "string" ? a[field].localeCompare(b[field]) : (b[field] ?? 0) - (a[field] ?? 0); });
  const arrow = field => state.studentsSort === field ? " ↕" : "";
  return `${header("Students", "Compare PACE use by student for the selected range.", range, "Students")}<section class="panel"><div class="table-toolbar"><div><h2>Student activity</h2><p>${rows.length} student${rows.length === 1 ? "" : "s"} with completed visits</p></div><label class="search-field"><span>Search</span><input id="studentsSearch" type="search" placeholder="Search students" value="${esc(state.studentsSearch ?? "")}"></label></div>${rows.length ? `<div class="table-scroll"><table><thead><tr><th><button data-sort="student">Student${arrow("student")}</button></th><th><button data-sort="visits">Visits${arrow("visits")}</button></th><th><button data-sort="totalMinutes">Total PACE time${arrow("totalMinutes")}</button></th><th><button data-sort="averageDuration">Avg. duration${arrow("averageDuration")}</button></th><th><button data-sort="lastVisit">Last visit${arrow("lastVisit")}</button></th><th><button data-sort="scmEvents">SCM events${arrow("scmEvents")}</button></th></tr></thead><tbody>${rows.map(row => `<tr class="clickable-row" data-student="${esc(row.student)}"><td><a href="#/pace/students/${encodeURIComponent(row.student)}">${esc(row.student)}</a></td><td>${row.visits}</td><td>${formatMinutes(row.totalMinutes)}</td><td>${formatMinutes(row.averageDuration)}</td><td>${esc(formatDate(row.lastVisit))}</td><td>${row.scmEvents || "—"}</td></tr>`).join("")}</tbody></table></div>` : emptyState("No students found", "Try a different search or date range.")}</section>${activeVisit ? detailModal(activeVisit, state.followUps, state.demo, state.adminReviews, state.mutationError, state.production, state) : ""}`;
}

export function renderStudentDetail(visits, range, student, followUps, activeVisit, demo = true, adminReviews = {}, mutationError = "", production = {}, ui = {}) {
  const selected = filterVisits(activeVisits(visits, adminReviews), { ...range, student }); const summary = summarize(selected, range); const history = [...selected].sort(sortNewest); const reasons = groupVisitsByReason(selected); const interventions = groupVisitsByIntervention(selected);
  if (!student || !selected.length) return `${header("Student detail", "No PACE records matched this student and date range.", range, "Students")}<a class="back-link" href="#/pace/students">← Back to students</a>${emptyState("No matching visits", "Return to Students and choose another student.")}`;
  return `${header(student, `PACE-specific detail for ${formatDateRange(range)}.`, range, "Student detail")}<a class="back-link" href="#/pace/students">← Back to students</a><div class="kpi-grid compact">${metricCard("Visits", summary.visits)}${metricCard("Total PACE time", formatMinutes(calculateTotalDuration(selected)))}${metricCard("Average duration", formatMinutes(calculateAverageDuration(selected)))}${metricCard("Last visit", formatDate(history[0]?.date))}${metricCard("SCM events", summary.scmEvents === null ? "—" : summary.scmEvents)}</div><div class="detail-columns"><div>${barList("Reasons", reasons)}${barList("Interventions / supports", interventions)}</div><section class="panel"><div class="panel-heading"><div><h2>Visit history</h2><p>Chronological records for this student in the selected range.</p></div></div><div class="history-list">${history.map(visit => `<button class="history-item" data-visit="${esc(visit.id)}"><span class="history-date">${esc(formatDate(visit.date))}</span><span class="history-main"><strong>${esc(visit.timeIn || "Time not recorded")}${visit.timeOut ? `–${visit.timeOut}` : ""}</strong><span>${esc(visit.room || "Room not recorded")} · ${esc(visit.reasons.join(", ") || "Reason not recorded")}</span></span><span class="history-end"><strong>${formatMinutes(visit.durationMinutes)}</strong>${followUpBadge(followUpFor(followUps, visit.id))}</span></button>`).join("")}</div></section></div>${activeVisit ? detailModal(activeVisit, followUps, demo, adminReviews, mutationError, production, ui) : ""}`;
}

function renderActivityPage({ range, filters, rows, select, unique, state, activeVisit }) {
  const filterMarkup = `<label class="filter-field wide"><span>Search</span><input data-activity-filter="search" type="search" placeholder="Student, room, reason, specialist…" value="${esc(filters.search ?? "")}"></label>${select("student", "Student", unique("student"))}${select("specialist", "Specialist", unique("specialist"))}${select("room", "Room", unique("room"))}${select("reason", "Reason", unique("reason"))}<label class="filter-field"><span>SCM</span><select data-activity-filter="scm"><option value="">All</option><option value="yes" ${filters.scm === "yes" ? "selected" : ""}>Yes</option><option value="no" ${filters.scm === "no" ? "selected" : ""}>No</option></select></label><label class="filter-field"><span>Review Status</span><select data-activity-filter="reviewStatus"><option value="">All active</option><option value="${REVIEW_STATUS.UNREVIEWED}" ${filters.reviewStatus === REVIEW_STATUS.UNREVIEWED ? "selected" : ""}>Unreviewed</option><option value="${REVIEW_STATUS.REVIEWED}" ${filters.reviewStatus === REVIEW_STATUS.REVIEWED ? "selected" : ""}>Reviewed</option><option value="${REVIEW_STATUS.NEEDS_FOLLOW_UP}" ${filters.reviewStatus === REVIEW_STATUS.NEEDS_FOLLOW_UP ? "selected" : ""}>Needs Follow-Up</option><option value="voided" ${filters.reviewStatus === "voided" ? "selected" : ""}>Voided</option></select></label><label class="filter-field"><span>Follow-Up Status</span><select data-activity-filter="followUpStatus"><option value="">All</option><option value="none" ${filters.followUpStatus === "none" ? "selected" : ""}>No Follow-Up</option><option value="needs-review" ${filters.followUpStatus === "needs-review" ? "selected" : ""}>Needs Review</option><option value="in-review" ${filters.followUpStatus === "in-review" ? "selected" : ""}>In Review</option><option value="complete" ${filters.followUpStatus === "complete" ? "selected" : ""}>Follow-Up Complete</option></select></label>`;
  const body = [...rows].sort(sortNewest).map(visit => `<tr class="clickable-row" data-visit="${esc(visit.id)}"><td>${esc(formatDate(visit.date))}<br><span class="muted">${esc(visit.timeIn || "—")}${visit.timeOut ? `–${esc(visit.timeOut)}` : " · open"}</span></td><td><strong>${esc(visit.student || "Unnamed")}</strong></td><td>${esc(visit.room || "—")}</td><td>${esc(visit.reasons.join(", ") || "—")}</td><td>${esc(visit.interventions.join(", ") || "—")}</td><td>${esc(visit.specialists.join(", ") || "—")}</td><td>${formatMinutes(visit.durationMinutes)}</td><td>${visit.scmUsed === null ? "—" : pill(visit.scmUsed ? "Yes" : "No", visit.scmUsed ? "accent" : "neutral")}</td><td>${followUpBadge(followUpFor(state.followUps, visit.id))}</td><td>${isVoided(visit, state.adminReviews) ? pill("Voided", "neutral") : pill(reviewStatusLabel(adminReviewFor(state.adminReviews, visit.id).status), adminReviewFor(state.adminReviews, visit.id).status === REVIEW_STATUS.REVIEWED ? "accent" : "neutral")}</td><td class="admin-action-cell"><button class="button secondary compact-button" data-open-visit="${esc(visit.id)}">Edit Submission</button></td></tr>`).join("");
  return `${header("Activity Log", "Use Custom range to find historical submissions beyond the default 30-day window.", range, "Activity Log")}<section class="panel"><div class="filter-grid">${filterMarkup}</div><div class="table-toolbar log-toolbar"><div><h2>PACE visits</h2><p>${rows.length} matching record${rows.length === 1 ? "" : "s"} · ${state.demo ? "Synthetic workflow" : "Production source records are read-only"}</p></div></div>${rows.length ? `<div class="table-scroll"><table><thead><tr><th>Date / time</th><th>Student</th><th>Room</th><th>Reason</th><th>Support</th><th>Specialist</th><th>Duration</th><th>SCM</th><th>Follow-Up</th><th>Review</th><th>Actions</th></tr></thead><tbody>${body}</tbody></table></div>` : emptyState("No matching visits", "Try clearing a filter or choosing a wider date range.")}</section>${activeVisit ? detailModal(activeVisit, state.followUps, state.demo, state.adminReviews, state.mutationError, state.production, state) : ""}`;
}

export function renderActivity(visits, range, state, activeVisit) {
  const all = filterVisits(visits, range); const filters = state.activityFilters ?? {};
  const rows = filterVisits(all, { ...filters, from: range.from, to: range.to }).filter(visit => matchesFollowUpStatus(visit, state.followUps, filters.followUpStatus)).filter(visit => matchesReviewStatus(visit, state.adminReviews, filters.reviewStatus));
  const unique = key => [...new Set(all.flatMap(v => key === "specialist" ? v.specialists : key === "reason" ? v.reasons : [v[key]]).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const select = (id, label, values) => `<label class="filter-field"><span>${esc(label)}</span><select data-activity-filter="${id}"><option value="">All</option>${values.map(value => `<option value="${esc(value)}" ${filters[id] === value ? "selected" : ""}>${esc(value)}</option>`).join("")}</select></label>`;
  return renderActivityPage({ range, filters, rows, select, unique, state, activeVisit });
}
